files.content:
:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --accent: #41a6f6;
  --accent-2: #73eff7;
  --text: #f4f4f4;
  --muted: #94b0c2;
  --error: #ff6b6b;
  --border: #566c86;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%),
                    linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 #0f1020;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
h1 {
  margin: 0;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent-2);
  text-shadow: 3px 3px 0 #0f1020;
}
h1 span { color: var(--accent); }
.formula {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
  line-height: 1.5;
  border-left: 3px solid var(--accent);
  padding-left: 8px;
  word-break: break-word;
}
.field { display: flex; flex-direction: column; gap: 6px; }
label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent-2);
}
input, select, button {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 12px;
  background: #1f2547;
  color: var(--text);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
}
input:focus, select:focus, button:focus-visible {
  border-color: var(--accent-2);
  box-shadow: 0 0 0 3px rgba(115, 239, 247, 0.35);
}
input:hover, select:hover { border-color: var(--accent); }
button {
  background: var(--accent);
  color: #0f1020;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  border-color: #1f2547;
  box-shadow: 4px 4px 0 #0f1020;
  transition: transform 0.05s, box-shadow 0.05s;
}
button:hover { background: var(--accent-2); }
button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}
.result-box {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #1f2547;
  border: 3px solid var(--border);
  padding: 12px 16px;
}
.result-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}
#result {
  font-size: 1.4rem;
  font-weight: bold;
  color: var(--accent-2);
  text-shadow: 2px 2px 0 #0f1020;
}
#result.error { color: var(--error); }
@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.25rem; }
  .formula { font-size: 0.75rem; }
}

const tempInput = document.getElementById('temperature');
const directionSelect = document.getElementById('direction');
const convertBtn = document.getElementById('convert');
const resultEl = document.getElementById('result');

function convert() {
  const raw = tempInput.value.trim();
  resultEl.classList.remove('error');

  if (raw === '') {
    resultEl.textContent = 'Error';
    resultEl.classList.add('error');
    return;
  }

  const x = Number(raw);
  if (!Number.isFinite(x)) {
    resultEl.textContent = 'Error';
    resultEl.classList.add('error');
    return;
  }

  const direction = directionSelect.value;
  let value;
  if (direction === 'c-to-f') {
    value = x * 9 / 5 + 32;
  } else if (direction === 'f-to-c') {
    value = (x - 32) * 5 / 9;
  } else {
    resultEl.textContent = 'Error';
    resultEl.classList.add('error');
    return;
  }

  if (!Number.isFinite(value)) {
    resultEl.textContent = 'Error';
    resultEl.classList.add('error');
    return;
  }

  resultEl.textContent = value.toFixed(2);
}

convertBtn.addEventListener('click', convert);

tempInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    convert();
  }
});
